 31	    /**
 32	     * Represent a field of the given dimensions.
 33	     * 
 34	     * @param depth The depth of the field.
 35	     * @param width The width of the field.
 36	     */
 37	    public Field(int depth, int width, Time time, Weather weather)
 38	    {
 39	        this.depth = depth;
 40	        this.width = width;
 41	        field = new GridSpace[depth][width];
 42	        this.time = time;
 43	        this.weather = weather;
 44	        populationCounts = new LinkedHashMap<>();
 45	    }
