 47	    /**
 48	     * Empty the field.
 49	     */
 50	    public void clear()
 51	    {
 52	        populationCounts.clear();
 53	        for(int row = 0; row < depth; row++) 
 54	        {
 55	            for(int col = 0; col < width; col++) 
 56	            {
 57	                field[row][col] = new GridSpace();
