175	    /**
176	     * Get a shuffled list of the free adjacent locations.
177	     * 
178	     * @param location Get locations adjacent to this.
179	     * @param objectType Object type to avoid.
180	     * 
181	     * @return A list of free adjacent locations.
182	     */
183	    public List<Location> getFreeAdjacentLocations(Location location, Class<?> objectType)
184	    {
185	        List<Location> free = new LinkedList<>();
186	        List<Location> adjacent = adjacentLocations(location);
187	        
188	        for(Location next : adjacent) 
189	        {
190	            if(getObjectAt(next, objectType) == null) 
191	            {
192	                free.add(next);
193	            }
194	        }
195	        
196	        return free;
197	    } 
