199	    /**
200	     * Try to find a free location that is adjacent to the
201	     * given location. If there is none, return null.
202	     * The returned location will be within the valid bounds
203	     * of the field.
204	     * 
205	     * @param location The location from which to generate an adjacency.
206	     * @param objectType type to avoid.
207	     * 
208	     * @return A valid location within the grid area.
209	     */
210	    public Location freeAdjacentLocation(Location location, Class<?> objectType)
211	    {
212	        // The available free ones.
213	        List<Location> free = getFreeAdjacentLocations(location, objectType);
214	        
215	        if(free.size() > 0) 
216	        {
217	            return free.get(0);
218	        }
219	        else
220	        {
221	            return null;
222	        }
223	    }
