225	    /**
226	     * Return a shuffled list of locations adjacent to the given one.
227	     * The list will not include the location itself.
228	     * All locations will lie within the grid.
229	     * 
230	     * @param location The location from which to generate adjacencies.
231	     * 
232	     * @return A list of locations adjacent to that given.
233	     */
234	    public List<Location> adjacentLocations(Location location)
235	    {
236	        assert location != null : "Null location passed to adjacentLocations";
237	        // The list of locations to be returned.
238	        List<Location> locations = new LinkedList<>();
239	        
240	        if(location != null)
241	        {
242	            int row = location.getRow();
243	            int col = location.getCol();
244	            
245	            for(int roffset = -1; roffset <= 1; roffset++) 
246	            {
247	                int nextRow = row + roffset;
248	                
249	                if(nextRow >= 0 && nextRow < depth) 
250	                {
251	                    for(int coffset = -1; coffset <= 1; coffset++) 
252	                    {
253	                        int nextCol = col + coffset;
254	                        
255	                        // Exclude invalid locations and the original location.
256	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) 
257	                        {
258	                            locations.add(new Location(nextRow, nextCol));
259	                        }
260	                    }
261	                }
262	            }
263	            
264	            // Shuffle the list. Several other methods rely on the list
265	            // being in a random order.
266	            Collections.shuffle(locations, rand);
267	        }
268	        
269	        return locations;
270	    }
