 5	/**
 6	 * This class collects and provides some statistical data on the state 
 7	 * of a field. It is flexible: it will create and maintain a counter 
 8	 * for any class of object that is found within the field.
 9	 *
10	 * @version 26/02/2022
11	 */
12	public class FieldStats
13	{
14	    // Counters for each type of entity (lion, zebra, etc.) in the simulation.
15	    private Map<Class<?>, Counter> counters;
16	
17	    /**
18	     * Construct a FieldStats object.
19	     */
20	    public FieldStats()
21	    {
22	        // Set up a collection for counters for each type of animal that
23	        // we might find
24	        counters = new LinkedHashMap<>();
25	    }
26	
27	    /**
28	     * Get details of what is in the field.
29	     * 
30	     * @param field The field to get the population details of.
31	     * 
32	     * @return A string describing what is in the field.
33	     */
34	    public String getPopulationDetails(Field field)
35	    {
36	        StringBuilder buffer = new StringBuilder();
37	
38	        syncCounts(field);
39	        for(Counter info : counters.values()) {
40	            buffer.append(info.getName());
41	            buffer.append(": ");
42	            buffer.append(info.getCount());
43	            buffer.append(' ');
44	        }
45	        return buffer.toString();
46	    }
47	    
48	    /**
49	     * Invalidate the current set of statistics; reset all 
50	     * counts to zero.
51	     */
52	    private void reset()
53	    {
54	        for(Counter count : counters.values()) {
55	            count.reset();
56	        }
57	    }
58	
59	    /**
60	     * Determine whether the simulation is still viable.
61	     * I.e., should it continue to run.
62	     * 
63	     * @return true If there is more than one species alive.
64	     */
65	    public boolean isViable(Field field)
66	    {
67	        return field.getActivePopulationTypeCount() > 1;
68	    }
69	
70	    /**
71	     * Synchronise display counters with the populations tracked by Field.
72	     */
73	    private void syncCounts(Field field)
74	    {
75	        reset();
76	
77	        Map<Class<?>, Integer> populations = field.getPopulationCounts();
78	        populations.entrySet().stream()
79	            .sorted(Comparator.comparing(entry -> entry.getKey().getName()))
80	            .forEach(entry -> {
81	                Counter counter = counters.get(entry.getKey());
82	                if(counter == null) {
83	                    counter = new Counter(entry.getKey().getName());
84	                    counters.put(entry.getKey(), counter);
85	                }
86	
87	                counter.setCount(entry.getValue());
88	            });
89	    }
90	}

